input.formalDefinitions:
by
  intro n hn
  let parityMatrix : Matrix (Fin n) (Fin n) ℤ → Matrix (Fin n) (Fin n) (ZMod 2) :=
    fun B i j => (B i j : ZMod 2)
  let T : Matrix (Fin n) (Fin n) (ZMod 2) → Matrix (Fin n) (Fin n) (ZMod 2) :=
    fun X i j => X i j + (∑ k : Fin n, X i k) + (∑ k : Fin n, X k j)
  let r : Matrix (Fin n) (Fin n) (ZMod 2) → Fin n → ZMod 2 :=
    fun X i => ∑ j : Fin n, X i j
  let c : Matrix (Fin n) (Fin n) (ZMod 2) → Fin n → ZMod 2 :=
    fun X j => ∑ i : Fin n, X i j
  let t : Matrix (Fin n) (Fin n) (ZMod 2) → ZMod 2 :=
    fun X => ∑ i : Fin n, ∑ j : Fin n, X i j
  let oddRows : Matrix (Fin n) (Fin n) (ZMod 2) → Finset (Fin n) :=
    fun X => Finset.univ.filter (fun i : Fin n => r X i = (1 : ZMod 2))
  let oddCols : Matrix (Fin n) (Fin n) (ZMod 2) → Finset (Fin n) :=
    fun X => Finset.univ.filter (fun j : Fin n => c X j = (1 : ZMod 2))
  let oddRowCount : Matrix (Fin n) (Fin n) (ZMod 2) → ℕ :=
    fun X => (oddRows X).card
  let oddColCount : Matrix (Fin n) (Fin n) (ZMod 2) → ℕ :=
    fun X => (oddCols X).card
  let onesCount : Matrix (Fin n) (Fin n) (ZMod 2) → ℕ :=
    fun X => (Finset.univ.filter (fun p : Fin n × Fin n => X p.1 p.2 = (1 : ZMod 2))).card
  let countEven : Matrix (Fin n) (Fin n) ℤ → Matrix (Fin n) (Fin n) ℕ → ℕ :=
    fun B x => (Finset.univ.filter (fun p : Fin n × Fin n =>
      Even (B p.1 p.2 + (∑ k : Fin n, (x p.1 k : ℤ)) +
        (∑ k : Fin n, (x k p.2 : ℤ)) - (x p.1 p.2 : ℤ)))).card
  let i0 : Fin n := ⟨0, hn⟩
  let Bbad : Matrix (Fin n) (Fin n) (ZMod 2) :=
    fun i j => if i = i0 ∧ j.val < n - 1 then (1 : ZMod 2) else 0
